-- 27-10-2026 (Besluit 131): DCG-profiel versie 2. Alleen de onderdelen die veranderen; de rest van het profiel blijft zoals het is.
-- Leerlijnen krijgen een kant (aanval/verdediging) en de kandidaten voor de 6e leerlijn; 8 lege plekken voor spelprincipes;
-- leerdoelen als observeerbaar gedrag (nog leeg); sjabloon DCG 75 (pilot). Bron: supabase/profielen/dcg.json.
update public.rij set data = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,
    '{onderdelen,leerlijnen}', $j${"status": "eigen", "naam": "Individuele voetbalvaardigheden (universele leerlijnen)", "items": [{"id": "ll-1v1-aanvallend", "naam": "1v1 aanvallend", "kern": "manipuleren", "kant": "aanval"}, {"id": "ll-aannemen", "naam": "Aannemen en meenemen", "kern": "voorbereiden", "kant": "aanval"}, {"id": "ll-passen", "naam": "Passen", "kern": "helpen", "kant": "aanval"}, {"id": "ll-vrijkomen", "naam": "Vrijkomen", "kern": "timen", "kant": "aanval"}, {"id": "ll-1v1-verdedigen", "naam": "1v1 verdedigen en bal veroveren", "kern": "controleren", "kant": "verdediging"}, {"id": "ll-6", "naam": null, "kern": null, "status": "controleren", "noot": "Zesde leerlijn: nog niet definitief. We vergelijken beschermen/vrijmaken met schieten/afronden.", "kandidaten": ["Beschermen / vrijmaken", "Schieten / afronden"]}]}$j$::jsonb),
    '{onderdelen,spelprincipes}', $j${"status": "leeg", "items": [{"id": "sp-aan-1", "teamfunctie": "tf-aanvallen", "naam": null, "status": "leeg"}, {"id": "sp-aan-2", "teamfunctie": "tf-aanvallen", "naam": null, "status": "leeg"}, {"id": "sp-ver-1", "teamfunctie": "tf-verdedigen", "naam": null, "status": "leeg"}, {"id": "sp-ver-2", "teamfunctie": "tf-verdedigen", "naam": null, "status": "leeg"}, {"id": "sp-omva-1", "teamfunctie": "tf-omsch-va", "naam": null, "status": "leeg"}, {"id": "sp-omva-2", "teamfunctie": "tf-omsch-va", "naam": null, "status": "leeg"}, {"id": "sp-omav-1", "teamfunctie": "tf-omsch-av", "naam": null, "status": "leeg"}, {"id": "sp-omav-2", "teamfunctie": "tf-omsch-av", "naam": null, "status": "leeg"}], "noot": "Acht voorlopige spelprincipes voor O13, twee per teamfunctie. De inhoud stellen we nog vast; lege plekken zien trainers niet."}$j$::jsonb),
    '{onderdelen,leerdoelenPerLeeftijd}', $j${"status": "leeg", "items": [], "veld": {"id": "vaste id, bijv. ld-o13-scannen", "gedrag": "observeerbaar gedrag, bijv. \"kijkt over de schouder vóór balontvangst\"", "leeftijd": "bijv. O13", "leerlijn": "id van een leerlijn (optioneel)", "spelprincipe": "id van een spelprincipe (optioneel)", "kant": "aanval of verdediging (bepaalt het perspectief van de weerstand)"}, "noot": "Leerdoelen beschrijven observeerbaar gedrag en kunnen aan meerdere vormen gekoppeld worden. Wordt nog uitgewerkt."}$j$::jsonb),
    '{onderdelen,trainingsopbouw}', $j${"status": "eigen", "sjablonen": [{"id": "dcg-75", "naam": "DCG 75", "minuten": 75, "blokken": [{"blok": "start", "naam": "Start", "min": 8}, {"blok": "A1", "min": 6, "fase": "f-oefenleer"}, {"blok": "S", "min": 3}, {"blok": "A2", "min": 10, "fase": "f-toepassing"}, {"blok": "B1", "min": 6, "fase": "f-oefenleer"}, {"blok": "S", "min": 3}, {"blok": "B2", "min": 10, "fase": "f-toepassing"}, {"blok": "P", "naam": "Partij", "min": 22, "fase": "f-toepassing"}], "overig": {"naam": "Ombouw, wissels, afsluiting", "min": 7}}], "spacing": {"definitie": null, "noot": "Wat spacing inhoudelijk is (loslaten, herstel, contrast of spelend leren), stellen we nog vast. Tot dan: vrij in te vullen, telt voor geen leerdoel."}, "noot": "Pilot: twee vaardigheden (A en B), elk eerst oefenleer en dan toepassing, met spacing ertussen, en een partij. De tijden zijn een voorstel en blijven per training aanpasbaar."}$j$::jsonb),
    '{versie}', '2'::jsonb)
where club_id = 'dcg' and soort = 'profiel' and id = 'dcg' and (data->>'versie')::int < 2;
